// SearchBar — Gtk.SearchBar
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles searchbar with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface SearchBarProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Widget, from Gtk.SearchBar */
  child?: ReactNode

  /** Widget, from Gtk.SearchBar */
  keyCaptureWidget?: ReactNode

  /** gboolean, from Gtk.SearchBar */
  searchModeEnabled?: boolean

  /** gboolean, from Gtk.SearchBar */
  showCloseButton?: boolean
}

export function SearchBar({ className, children }: SearchBarProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
